-- Issue: GO-3356 - Family Planning visit persistence (main + product + LARC reason child tables)

CREATE TABLE BH_Visit_Family_Planning
(
	AD_Client_ID NUMERIC(10) NOT NULL,
	AD_Org_ID NUMERIC(10) NOT NULL,
	BH_Visit_Family_Planning_ID NUMERIC(10) NOT NULL,
	BH_Visit_Family_Planning_UU VARCHAR(36) DEFAULT NULL,
	BH_Visit_ID NUMERIC(10) NOT NULL,
	BH_Contraceptive_Oral CHAR(1) NOT NULL CHECK (BH_Contraceptive_Oral IN ('Y', 'N')) DEFAULT 'N',
	BH_Contraceptive_Injectable CHAR(1) NOT NULL CHECK (BH_Contraceptive_Injectable IN ('Y', 'N')) DEFAULT 'N',
	BH_Contraceptive_Implants CHAR(1) NOT NULL CHECK (BH_Contraceptive_Implants IN ('Y', 'N')) DEFAULT 'N',
	BH_Contraceptive_Emergency CHAR(1) NOT NULL CHECK (BH_Contraceptive_Emergency IN ('Y', 'N')) DEFAULT 'N',
	BH_Contraceptive_Iucd CHAR(1) NOT NULL CHECK (BH_Contraceptive_Iucd IN ('Y', 'N')) DEFAULT 'N',
	BH_Contraceptive_Condoms CHAR(1) NOT NULL CHECK (BH_Contraceptive_Condoms IN ('Y', 'N')) DEFAULT 'N',
	BH_Contraceptive_Vsc CHAR(1) NOT NULL CHECK (BH_Contraceptive_Vsc IN ('Y', 'N')) DEFAULT 'N',
	BH_Contraceptive_Natural_Fp CHAR(1) NOT NULL CHECK (BH_Contraceptive_Natural_Fp IN ('Y', 'N')) DEFAULT 'N',
	BH_Screening_Tb CHAR(1) NOT NULL CHECK (BH_Screening_Tb IN ('Y', 'N')) DEFAULT 'N',
	BH_Screening_Hiv CHAR(1) NOT NULL CHECK (BH_Screening_Hiv IN ('Y', 'N')) DEFAULT 'N',
	BH_Screening_Ipv CHAR(1) NOT NULL CHECK (BH_Screening_Ipv IN ('Y', 'N')) DEFAULT 'N',
	BH_Screening_Cervical CHAR(1) NOT NULL CHECK (BH_Screening_Cervical IN ('Y', 'N')) DEFAULT 'N',
	BH_Vsc_Btl CHAR(1) NOT NULL CHECK (BH_Vsc_Btl IN ('Y', 'N')) DEFAULT 'N',
	BH_Vsc_Vasectomy CHAR(1) NOT NULL CHECK (BH_Vsc_Vasectomy IN ('Y', 'N')) DEFAULT 'N',
	BH_First_Ever_Contraceptive_User VARCHAR(60) DEFAULT NULL,
	BH_First_Visit_Fp_At_Clinic VARCHAR(60) DEFAULT NULL,
	BH_Oral_Type_Of_Visit VARCHAR(60) DEFAULT NULL,
	BH_Injectable_Type_Of_Visit VARCHAR(60) DEFAULT NULL,
	BH_Injectable_Route VARCHAR(60) DEFAULT NULL,
	BH_Implants_Type_Of_Visit VARCHAR(60) DEFAULT NULL,
	BH_Emergency_Contraception_Given VARCHAR(60) DEFAULT NULL,
	BH_Iucd_Type_Of_Visit VARCHAR(60) DEFAULT NULL,
	BH_Vsc_Given VARCHAR(60) DEFAULT NULL,
	BH_Natural_Fp_Counseled VARCHAR(60) DEFAULT NULL,
	BH_Cycle_Beads_Given VARCHAR(60) DEFAULT NULL,
	BH_Postpartum_Fp VARCHAR(60) DEFAULT NULL,
	BH_Tb_Screening VARCHAR(60) DEFAULT NULL,
	BH_Hiv_Counseled_Tested VARCHAR(60) DEFAULT NULL,
	BH_Hiv_Results VARCHAR(60) DEFAULT NULL,
	BH_Ipv_Reproductive_Coercion VARCHAR(60) DEFAULT NULL,
	BH_Cervical_Cancer_Screening VARCHAR(60) DEFAULT NULL,
	BH_Cervical_Pap_Method VARCHAR(60) DEFAULT NULL,
	BH_Cervical_Results VARCHAR(60) DEFAULT NULL,
	BH_Referrals VARCHAR(60) DEFAULT NULL,
	BH_Referral_Community_From VARCHAR(60) DEFAULT NULL,
	BH_Referral_Community_To VARCHAR(60) DEFAULT NULL,
	BH_Emergency_Contraception_Notes TEXT DEFAULT NULL,
	BH_Referrals_Reason TEXT DEFAULT NULL,
	BH_Remarks TEXT DEFAULT NULL,
	Created TIMESTAMP NOT NULL DEFAULT getDate(),
	CreatedBy NUMERIC(10) NOT NULL,
	Description VARCHAR(255) DEFAULT NULL,
	IsActive CHAR(1) NOT NULL CHECK (IsActive IN ('Y', 'N')) DEFAULT 'Y',
	Updated TIMESTAMP NOT NULL DEFAULT getDate(),
	UpdatedBy NUMERIC(10) NOT NULL,
	CONSTRAINT BH_Visit_Family_Planning_Key PRIMARY KEY (BH_Visit_Family_Planning_ID),
	CONSTRAINT BH_Visit_Family_Planning_UU_idx UNIQUE (BH_Visit_Family_Planning_UU),
	CONSTRAINT BH_Visit_Family_Planning_Visit_idx UNIQUE (BH_Visit_ID)
);
ALTER TABLE BH_Visit_Family_Planning ADD CONSTRAINT ADClient_BHVisitFamilyPlanning FOREIGN KEY (AD_Client_ID) REFERENCES ad_client (ad_client_id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE BH_Visit_Family_Planning ADD CONSTRAINT ADOrg_BHVisitFamilyPlanning FOREIGN KEY (AD_Org_ID) REFERENCES ad_org (ad_org_id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE BH_Visit_Family_Planning ADD CONSTRAINT BHVisit_BHVisitFamilyPlanning FOREIGN KEY (BH_Visit_ID) REFERENCES bh_visit (bh_visit_id) DEFERRABLE INITIALLY DEFERRED;

